#### Phase 1: Basic Resource Monitoring and Threshold-Based Shedding (Week 1-2)

**Objective**: Implement simple CPU-based load shedding without priority classification, establishing monitoring infrastructure and basic rejection mechanism.

**Step 1.1 - Install Monitoring Dependencies** (Day 1)

Add Prometheus instrumentation and custom metrics collector NuGet packages:

```bash
# From PowerShell in project directory
dotnet add package prometheus-net.AspNetCore --version 8.2.1
dotnet add package prometheus-net.DotNetRuntime --version 4.4.0
dotnet add package System.Diagnostics.PerformanceCounter --version 8.0.0
```

**Step 1.2 - Implement Resource Monitor** (Day 1-2)

Create service collecting CPU, memory, and thread pool metrics:

```csharp
// Services/ResourceMonitor.cs
using System.Diagnostics;
using Prometheus;

namespace Gainwell.EligibilityApi.Services;

public interface IResourceMonitor
{
    ResourceState GetCurrentState();
    LoadLevel DetermineLoadLevel();
}

public class ResourceMonitor : IResourceMonitor, IDisposable
{
    private readonly ILogger<ResourceMonitor> _logger;
    private readonly ResourceMonitorOptions _options;

    // Prometheus metrics
    private static readonly Gauge CpuUtilization = Metrics.CreateGauge(
        "resource_monitor_cpu_utilization_percent",
        "Current CPU utilization percentage");
    private static readonly Gauge MemoryUtilization = Metrics.CreateGauge(
        "resource_monitor_memory_utilization_percent",
        "Current memory utilization percentage");
    private static readonly Gauge ThreadPoolUtilization = Metrics.CreateGauge(
        "resource_monitor_threadpool_utilization_percent",
        "Current thread pool utilization percentage");

    // Performance counters for Windows/.NET metrics
    private readonly PerformanceCounter? _cpuCounter;
    private readonly Process _currentProcess;
    private readonly Timer _collectionTimer;

    // Cached state (updated every 5 seconds)
    private ResourceState _currentState;
    private readonly object _stateLock = new();

    public ResourceMonitor(ILogger<ResourceMonitor> logger, IOptions<ResourceMonitorOptions> options)
    {
        _logger = logger;
        _options = options.Value;
        _currentProcess = Process.GetCurrentProcess();

        // Initialize CPU counter (Windows only - on Linux, use /proc/stat)
        try
        {
            if (OperatingSystem.IsWindows())
            {
                _cpuCounter = new PerformanceCounter(
                    "Processor",
                    "% Processor Time",
                    "_Total",
                    true);
                _cpuCounter.NextValue(); // Prime the counter
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Failed to initialize CPU performance counter, will use fallback");
        }

        // Start background collection
        _collectionTimer = new Timer(
            CollectMetrics,
            null,
            TimeSpan.Zero,
            TimeSpan.FromSeconds(5));
    }

    private void CollectMetrics(object? state)
    {
        try
        {
            var cpuPercent = GetCpuUtilization();
            var memoryPercent = GetMemoryUtilization();
            var threadPoolPercent = GetThreadPoolUtilization();

            var newState = new ResourceState
            {
                CpuPercent = cpuPercent,
                MemoryPercent = memoryPercent,
                ThreadPoolPercent = threadPoolPercent,
                Timestamp = DateTime.UtcNow
            };

            lock (_stateLock)
            {
                _currentState = newState;
            }

            // Update Prometheus metrics
            CpuUtilization.Set(cpuPercent);
            MemoryUtilization.Set(memoryPercent);
            ThreadPoolUtilization.Set(threadPoolPercent);

            _logger.LogDebug(
                "Resource state: CPU={CpuPercent:F1}%, Memory={MemoryPercent:F1}%, ThreadPool={ThreadPoolPercent:F1}%",
                cpuPercent, memoryPercent, threadPoolPercent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error collecting resource metrics");
        }
    }

    private double GetCpuUtilization()
    {
        try
        {
            if (_cpuCounter != null)
            {
                return _cpuCounter.NextValue();
            }

            // Fallback: use process CPU time (less accurate for system-wide CPU)
            _currentProcess.Refresh();
            var totalCpuTime = _currentProcess.TotalProcessorTime.TotalMilliseconds;
            var elapsedTime = (DateTime.UtcNow - _currentProcess.StartTime).TotalMilliseconds;
            var cpuPercent = (totalCpuTime / elapsedTime / Environment.ProcessorCount) * 100;
            return Math.Min(cpuPercent, 100);
        }
        catch
        {
            return 0; // Return 0 on error rather than failing
        }
    }

    private double GetMemoryUtilization()
    {
        try
        {
            _currentProcess.Refresh();
            var workingSet = _currentProcess.WorkingSet64;

            // On Linux, check cgroup memory limit
            var memoryLimit = GetContainerMemoryLimit() ?? GetSystemMemory();

            return (workingSet / (double)memoryLimit) * 100;
        }
        catch
        {
            return 0;
        }
    }

    private long? GetContainerMemoryLimit()
    {
        // Check Kubernetes cgroup memory limit (Linux)
        try
        {
            if (File.Exists("/sys/fs/cgroup/memory/memory.limit_in_bytes"))
            {
                var limitStr = File.ReadAllText("/sys/fs/cgroup/memory/memory.limit_in_bytes").Trim();
                if (long.TryParse(limitStr, out var limit) && limit < long.MaxValue)
                {
                    return limit;
                }
            }
        }
        catch { }

        return null;
    }

    private long GetSystemMemory()
    {
        // Fallback to system memory if container limit not found
        if (OperatingSystem.IsWindows())
        {
            var memStatus = new NativeMethods.MEMORYSTATUSEX();
            if (NativeMethods.GlobalMemoryStatusEx(memStatus))
            {
                return (long)memStatus.ullTotalPhys;
            }
        }

        // Default 4GB if detection fails
        return 4L * 1024 * 1024 * 1024;
    }

    private double GetThreadPoolUtilization()
    {
        ThreadPool.GetAvailableThreads(out var availableWorker, out var availableIo);
        ThreadPool.GetMaxThreads(out var maxWorker, out var maxIo);

        var usedWorker = maxWorker - availableWorker;
        return (usedWorker / (double)maxWorker) * 100;
    }

    public ResourceState GetCurrentState()
    {
        lock (_stateLock)
        {
            return _currentState;
        }
    }

    public LoadLevel DetermineLoadLevel()
    {
        var state = GetCurrentState();

        // Determine load level based on highest resource utilization
        var maxUtilization = Math.Max(
            state.CpuPercent,
            Math.Max(state.MemoryPercent, state.ThreadPoolPercent));

        return maxUtilization switch
        {
            < 70 => LoadLevel.Normal,
            < 85 => LoadLevel.Moderate,
            < 95 => LoadLevel.Heavy,
            _ => LoadLevel.Critical
        };
    }

    public void Dispose()
    {
        _collectionTimer?.Dispose();
        _cpuCounter?.Dispose();
        _currentProcess?.Dispose();
    }
}

public record ResourceState
{
    public double CpuPercent { get; init; }
    public double MemoryPercent { get; init; }
    public double ThreadPoolPercent { get; init; }
    public DateTime Timestamp { get; init; }
}

public enum LoadLevel
{
    Normal,    // < 70% utilization
    Moderate,  // 70-85%
    Heavy,     // 85-95%
    Critical   // > 95%
}

public class ResourceMonitorOptions
{
    public double CpuThreshold { get; set; } = 85;
    public double MemoryThreshold { get; set; } = 80;
    public double ThreadPoolThreshold { get; set; } = 85;
}

// Windows-specific P/Invoke for memory status
internal static class NativeMethods
{
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Auto)]
    internal class MEMORYSTATUSEX
    {
        public uint dwLength = (uint)Marshal.SizeOf<MEMORYSTATUSEX>();
        public uint dwMemoryLoad;
        public ulong ullTotalPhys;
        public ulong ullAvailPhys;
        public ulong ullTotalPageFile;
        public ulong ullAvailPageFile;
        public ulong ullTotalVirtual;
        public ulong ullAvailVirtual;
        public ulong ullAvailExtendedVirtual;
    }

    [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    internal static extern bool GlobalMemoryStatusEx([In, Out] MEMORYSTATUSEX lpBuffer);
}
```

**Step 1.3 - Implement Basic Load Shedding Middleware** (Day 2-3)

Create middleware rejecting requests when CPU exceeds threshold:

```csharp
// Middleware/LoadSheddingMiddleware.cs
using Microsoft.AspNetCore.Http;
using Prometheus;

namespace Gainwell.EligibilityApi.Middleware;

public class LoadSheddingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<LoadSheddingMiddleware> _logger;
    private readonly LoadSheddingOptions _options;

    // Prometheus metrics
    private static readonly Counter RequestsTotal = Metrics.CreateCounter(
        "loadshedding_requests_total",
        "Total requests processed by load shedding middleware",
        new CounterConfiguration { LabelNames = new[] { "decision", "load_level" } });

    private static readonly Gauge ShedRate = Metrics.CreateGauge(
        "loadshedding_shed_rate_percent",
        "Current shed rate percentage (1-minute rolling window)");

    private static readonly Histogram SheddingDecisionDuration = Metrics.CreateHistogram(
        "loadshedding_decision_duration_seconds",
        "Time taken to make shedding decision",
        new HistogramConfiguration
        {
            Buckets = Histogram.ExponentialBuckets(0.0001, 2, 10) // 0.1ms to 51ms
        });

    public LoadSheddingMiddleware(
        RequestDelegate next,
        ILogger<LoadSheddingMiddleware> logger,
        IOptions<LoadSheddingOptions> options)
    {
        _next = next;
        _logger = logger;
        _options = options.Value;
    }

    public async Task InvokeAsync(HttpContext context, IResourceMonitor resourceMonitor)
    {
        // Skip shedding for health checks and metrics endpoints
        if (IsExcludedPath(context.Request.Path))
        {
            await _next(context);
            return;
        }

        using var _ = SheddingDecisionDuration.NewTimer();

        // Get current system state
        var loadLevel = resourceMonitor.DetermineLoadLevel();
        var state = resourceMonitor.GetCurrentState();

        // Determine if request should be shed
        var shouldShed = ShouldShedRequest(loadLevel, state);

        if (shouldShed)
        {
            // Reject request
            RequestsTotal.WithLabels("rejected", loadLevel.ToString()).Inc();

            _logger.LogWarning(
                "Load shedding request: Path={Path}, LoadLevel={LoadLevel}, CPU={CpuPercent:F1}%, Memory={MemoryPercent:F1}%",
                context.Request.Path, loadLevel, state.CpuPercent, state.MemoryPercent);

            await WriteRejectionResponse(context, loadLevel, state);
            return;
        }

        // Accept request
        RequestsTotal.WithLabels("accepted", loadLevel.ToString()).Inc();

        // Continue pipeline
        await _next(context);
    }

    private bool ShouldShedRequest(LoadLevel loadLevel, ResourceState state)
    {
        // Simple threshold-based shedding (Phase 1)
        // Later phases will add priority-based logic

        return loadLevel switch
        {
            LoadLevel.Normal => false,     // No shedding
            LoadLevel.Moderate => false,   // No shedding yet (autoscaling handles it)
            LoadLevel.Heavy => Random.Shared.NextDouble() < 0.25,  // Shed 25% randomly
            LoadLevel.Critical => Random.Shared.NextDouble() < 0.50, // Shed 50% randomly
            _ => false
        };
    }

    private bool IsExcludedPath(PathString path)
    {
        // Don't shed health checks or metrics
        return path.StartsWithSegments("/health") ||
               path.StartsWithSegments("/healthz") ||
               path.StartsWithSegments("/metrics") ||
               path.StartsWithSegments("/ready");
    }

    private async Task WriteRejectionResponse(HttpContext context, LoadLevel loadLevel, ResourceState state)
    {
        context.Response.StatusCode = StatusCodes.Status503ServiceUnavailable;

        // Set Retry-After header (seconds until client should retry)
        var retryAfterSeconds = loadLevel switch
        {
            LoadLevel.Moderate => 30,
            LoadLevel.Heavy => 60,
            LoadLevel.Critical => 120,
            _ => 60
        };
        context.Response.Headers["Retry-After"] = retryAfterSeconds.ToString();

        // Write structured error response
        var errorResponse = new
        {
            error = "ServiceOverloaded",
            message = "The service is currently experiencing high load and cannot process this request. Please retry after the specified delay.",
            loadLevel = loadLevel.ToString(),
            retryAfterSeconds = retryAfterSeconds,
            timestamp = DateTime.UtcNow,
            traceId = context.TraceIdentifier
        };

        context.Response.ContentType = "application/json";
        await context.Response.WriteAsJsonAsync(errorResponse);
    }
}

public class LoadSheddingOptions
{
    public bool Enabled { get; set; } = true;
    public List<string> ExcludedPaths { get; set; } = new() { "/health", "/metrics" };
}
```

**Step 1.4 - Configure in Startup** (Day 3)

Register services and middleware in Program.cs:

```csharp
// Program.cs
using Gainwell.EligibilityApi.Services;
using Gainwell.EligibilityApi.Middleware;
using Prometheus;

var builder = WebApplication.CreateBuilder(args);

// Add resource monitoring
builder.Services.Configure<ResourceMonitorOptions>(
    builder.Configuration.GetSection("ResourceMonitoring"));
builder.Services.AddSingleton<IResourceMonitor, ResourceMonitor>();

// Add load shedding configuration
builder.Services.Configure<LoadSheddingOptions>(
    builder.Configuration.GetSection("LoadShedding"));

// Other services...
builder.Services.AddControllers();

var app = builder.Build();

// Use Prometheus metrics endpoint
app.UseMetricServer(); // Exposes /metrics endpoint
app.UseHttpMetrics();  // Tracks HTTP request metrics

// Load shedding middleware EARLY in pipeline (before authentication)
app.UseMiddleware<LoadSheddingMiddleware>();

// Standard middleware
app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();

app.Run();
```

Configuration in appsettings.json:

```json
{
  "ResourceMonitoring": {
    "CpuThreshold": 85,
    "MemoryThreshold": 80,
    "ThreadPoolThreshold": 85
  },
  "LoadShedding": {
    "Enabled": true,
    "ExcludedPaths": [ "/health", "/healthz", "/metrics", "/ready" ]
  }
}
```

**Step 1.5 - Deploy and Validate** (Day 3-4)

Deploy to development environment, run load tests validating shedding behavior:

```powershell
# Load test with k6
k6 run --vus 200 --duration 5m load-test.js

# Monitor metrics in real-time
$metricsUrl = "http://eligibility-api-dev.gainwell.local/metrics"
while ($true) {
    curl $metricsUrl | Select-String "loadshedding_"
    Start-Sleep -Seconds 5
}
```

Expected behavior: At normal load (<70% CPU), 0% rejection. At 85%+ CPU, 25-50% rejection rate. Accepted requests maintain normal latency. After load decrease, shedding stops immediately.

