#### Phase 2: Priority-Based Shedding (Week 3-4)

**Objective**: Add request priority classification and priority-based shedding logic protecting critical operations.

**Step 2.1 - Define Priority Model** (Day 1)

Create priority enumeration and classification models:

```csharp
// Models/RequestPriority.cs
namespace Gainwell.EligibilityApi.Models;

public enum RequestPriority
{
    P0Critical = 0,  // Emergency care coordination, pharmacy POS
    P1High = 1,      // Provider inquiries, eligibility verification
    P2Normal = 2,    // Member portal, batch processing
    P3Low = 3        // Analytics, reporting, admin operations
}

public record PriorityClassification
{
    public RequestPriority Priority { get; init; }
    public string Source { get; init; } = string.Empty; // How priority determined
    public string Reason { get; init; } = string.Empty; // Why this priority assigned
}
```

**Step 2.2 - Implement Priority Classifier** (Day 1-2)

Create service determining request priority from multiple signals:

```csharp
// Services/PriorityClassifier.cs
using System.Security.Claims;

namespace Gainwell.EligibilityApi.Services;

public interface IPriorityClassifier
{
    PriorityClassification ClassifyRequest(HttpContext context);
}

public class PriorityClassifier : IPriorityClassifier
{
    private readonly ILogger<PriorityClassifier> _logger;
    private readonly PriorityClassifierOptions _options;

    // Prometheus metrics
    private static readonly Counter ClassificationsTotal = Metrics.CreateCounter(
        "priority_classifications_total",
        "Total priority classifications",
        new CounterConfiguration { LabelNames = new[] { "priority", "source" } });

    public PriorityClassifier(
        ILogger<PriorityClassifier> logger,
        IOptions<PriorityClassifierOptions> options)
    {
        _logger = logger;
        _options = options.Value;
    }

    public PriorityClassification ClassifyRequest(HttpContext context)
    {
        // Priority determination hierarchy (first match wins):
        // 1. Explicit claim in auth token (most trusted)
        // 2. API endpoint route metadata (configured per-endpoint)
        // 3. X-Request-Priority header (validated against auth)
        // 4. Client/tenant default priority
        // 5. Fallback default (P2-Normal)

        // Try claim-based priority
        var claimPriority = GetPriorityFromClaims(context.User);
        if (claimPriority.HasValue)
        {
            var classification = new PriorityClassification
            {
                Priority = claimPriority.Value,
                Source = "jwt_claim",
                Reason = $"Priority claim in authentication token"
            };

            ClassificationsTotal.WithLabels(claimPriority.Value.ToString(), "jwt_claim").Inc();
            return classification;
        }

        // Try endpoint metadata priority
        var endpointPriority = GetPriorityFromEndpoint(context);
        if (endpointPriority.HasValue)
        {
            var classification = new PriorityClassification
            {
                Priority = endpointPriority.Value,
                Source = "endpoint_metadata",
                Reason = $"Endpoint {context.Request.Path} configured with priority"
            };

            ClassificationsTotal.WithLabels(endpointPriority.Value.ToString(), "endpoint_metadata").Inc();
            return classification;
        }

        // Try header-based priority (must validate against allowed priorities for this client)
        var headerPriority = GetPriorityFromHeader(context);
        if (headerPriority.HasValue && IsHeaderPriorityAllowed(context, headerPriority.Value))
        {
            var classification = new PriorityClassification
            {
                Priority = headerPriority.Value,
                Source = "request_header",
                Reason = $"X-Request-Priority header validated against client permissions"
            };

            ClassificationsTotal.WithLabels(headerPriority.Value.ToString(), "request_header").Inc();
            return classification;
        }

        // Try client/tenant default
        var clientPriority = GetClientDefaultPriority(context.User);
        if (clientPriority.HasValue)
        {
            var classification = new PriorityClassification
            {
                Priority = clientPriority.Value,
                Source = "client_default",
                Reason = $"Default priority for client {GetClientId(context.User)}"
            };

            ClassificationsTotal.WithLabels(clientPriority.Value.ToString(), "client_default").Inc();
            return classification;
        }

        // Fallback to default priority
        var defaultClassification = new PriorityClassification
        {
            Priority = RequestPriority.P2Normal,
            Source = "default",
            Reason = "No priority signals found, using default P2-Normal"
        };

        ClassificationsTotal.WithLabels("P2Normal", "default").Inc();
        return defaultClassification;
    }

    private RequestPriority? GetPriorityFromClaims(ClaimsPrincipal user)
    {
        var priorityClaim = user.FindFirst("request_priority")?.Value;
        if (string.IsNullOrEmpty(priorityClaim))
            return null;

        return Enum.TryParse<RequestPriority>(priorityClaim, ignoreCase: true, out var priority)
            ? priority
            : null;
    }

    private RequestPriority? GetPriorityFromEndpoint(HttpContext context)
    {
        // Check endpoint metadata (set via attributes on controllers/actions)
        var endpoint = context.GetEndpoint();
        var metadata = endpoint?.Metadata.GetMetadata<PriorityAttribute>();
        return metadata?.Priority;
    }

    private RequestPriority? GetPriorityFromHeader(HttpContext context)
    {
        if (!context.Request.Headers.TryGetValue("X-Request-Priority", out var headerValue))
            return null;

        return Enum.TryParse<RequestPriority>(headerValue, ignoreCase: true, out var priority)
            ? priority
            : null;
    }

    private bool IsHeaderPriorityAllowed(HttpContext context, RequestPriority requestedPriority)
    {
        // Prevent abuse: clients can't claim priority higher than their auth allows
        var maxAllowedPriority = GetClientMaxPriority(context.User);
        return requestedPriority >= maxAllowedPriority; // Lower priority number = higher priority
    }

    private RequestPriority GetClientMaxPriority(ClaimsPrincipal user)
    {
        // Check max_priority claim (highest priority this client allowed to use)
        var maxPriorityClaim = user.FindFirst("max_priority")?.Value;
        if (Enum.TryParse<RequestPriority>(maxPriorityClaim, ignoreCase: true, out var maxPriority))
            return maxPriority;

        // Default: clients can use P1-High or lower (not P0-Critical unless explicitly granted)
        return RequestPriority.P1High;
    }

    private RequestPriority? GetClientDefaultPriority(ClaimsPrincipal user)
    {
        // Some clients have default priority (e.g., batch processors always P3-Low)
        var clientType = user.FindFirst("client_type")?.Value;

        return clientType switch
        {
            "batch_processor" => RequestPriority.P3Low,
            "analytics_service" => RequestPriority.P3Low,
            "reporting_service" => RequestPriority.P2Normal,
            _ => null
        };
    }

    private string GetClientId(ClaimsPrincipal user)
    {
        return user.FindFirst("client_id")?.Value ??
               user.FindFirst(ClaimTypes.NameIdentifier)?.Value ??
               "unknown";
    }
}

// Attribute for decorating controllers/actions with priority
[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method)]
public class PriorityAttribute : Attribute
{
    public RequestPriority Priority { get; }

    public PriorityAttribute(RequestPriority priority)
    {
        Priority = priority;
    }
}

public class PriorityClassifierOptions
{
    public RequestPriority DefaultPriority { get; set; } = RequestPriority.P2Normal;
}
```

**Step 2.3 - Update Load Shedding Middleware with Priority Logic** (Day 2-3)

Modify middleware to use priority in shedding decisions:

```csharp
// Middleware/LoadSheddingMiddleware.cs (updated ShouldShedRequest method)

private bool ShouldShedRequest(
    LoadLevel loadLevel,
    ResourceState state,
    PriorityClassification priority)
{
    // Priority-based shedding matrix
    // Lower priority requests shed first and more aggressively

    var shedRate = (loadLevel, priority.Priority) switch
    {
        // Normal load: shed nothing
        (LoadLevel.Normal, _) => 0.0,

        // Moderate load (70-85%): begin shedding P3 only
        (LoadLevel.Moderate, RequestPriority.P3Low) => 0.60,      // 60% P3 shed
        (LoadLevel.Moderate, _) => 0.0,                            // P0-P2 accepted

        // Heavy load (85-95%): shed P3 entirely, majority of P2
        (LoadLevel.Heavy, RequestPriority.P3Low) => 1.0,          // 100% P3 shed
        (LoadLevel.Heavy, RequestPriority.P2Normal) => 0.75,      // 75% P2 shed
        (LoadLevel.Heavy, _) => 0.0,                               // P0-P1 accepted

        // Critical load (>95%): shed everything except P0
        (LoadLevel.Critical, RequestPriority.P3Low) => 1.0,       // 100% P3 shed
        (LoadLevel.Critical, RequestPriority.P2Normal) => 1.0,    // 100% P2 shed
        (LoadLevel.Critical, RequestPriority.P1High) => 0.85,     // 85% P1 shed
        (LoadLevel.Critical, RequestPriority.P0Critical) => 0.0,  // P0 always accepted

        _ => 0.0
    };

    // Probabilistic shedding: generate random [0,1], shed if < shedRate
    return Random.Shared.NextDouble() < shedRate;
}
```

